async function run(){await db.initialize();console.log("Database initialized.");const e=db.models.settings;if(e){const n=await e.findOne({where:{key:"binarySettings"}});n?console.log("binarySettings value:",n.value):console.log("binarySettings not found!");const o=await e.findOne({where:{key:"spotChartEngine"}});o?console.log("spotChartEngine value:",o.value):console.log("spotChartEngine not found!")}else console.error("Settings model not found!");process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db");run().catch(e=>{console.error(e);process.exit(1)});